import base64
import hashlib
import hmac
import json
import os
import time


class AuthService:
    def __init__(self, secret_key: bytes, token_ttl: int = 3600):
        self.secret_key = secret_key
        self.token_ttl = token_ttl
        self.users = {}  # username -> {salt, password_hash, roles}

    def register_user(self, username: str, password: str, roles):
        if username in self.users:
            raise ValueError("duplicate user")
        salt = os.urandom(16)
        pwd_hash = hashlib.pbkdf2_hmac("sha256", password.encode(), salt, 100_000)
        self.users[username] = {
            "salt": salt,
            "password_hash": pwd_hash,
            "roles": set(roles),
        }

    def authenticate(self, username: str, password: str) -> str:
        user = self.users.get(username)
        if not user:
            raise ValueError("unknown user")
        candidate = hashlib.pbkdf2_hmac("sha256", password.encode(), user["salt"], 100_000)
        if not hmac.compare_digest(candidate, user["password_hash"]):
            raise ValueError("invalid login")

        payload = {
            "sub": username,
            "roles": sorted(user["roles"]),
            "exp": int(time.time()) + self.token_ttl,
        }
        payload_bytes = json.dumps(payload, separators=(",", ":")).encode()
        payload_b64 = base64.urlsafe_b64encode(payload_bytes).decode().rstrip("=")
        signature = hmac.new(self.secret_key, payload_b64.encode(), hashlib.sha256).digest()
        sig_b64 = base64.urlsafe_b64encode(signature).decode().rstrip("=")
        return f"{payload_b64}.{sig_b64}"

    def validate_token(self, token: str) -> dict:
        try:
            payload_b64, sig_b64 = token.split(".", 1)
        except ValueError:
            raise ValueError("invalid token")

        expected_sig = hmac.new(self.secret_key, payload_b64.encode(), hashlib.sha256).digest()
        actual_sig = self._b64decode(sig_b64)
        if not hmac.compare_digest(expected_sig, actual_sig):
            raise ValueError("invalid token")

        payload = json.loads(self._b64decode(payload_b64).decode())
        if payload.get("exp", 0) < int(time.time()):
            raise ValueError("expired token")
        return payload

    def authorize(self, token: str, required_role: str) -> bool:
        payload = self.validate_token(token)
        return required_role in payload.get("roles", [])

    @staticmethod
    def _b64decode(data: str) -> bytes:
        padding = "=" * (-len(data) % 4)
        return base64.urlsafe_b64decode(data + padding)


if __name__ == "__main__":
    auth = AuthService(secret_key=b"super-secret-key", token_ttl=600)
    auth.register_user("alice", "S3curePass!", {"admin", "editor"})
    token = auth.authenticate("alice", "S3curePass!")
    print("Token:", token)
    print("Payload:", auth.validate_token(token))
    print("Can access admin?", auth.authorize(token, "admin"))
    print("Can access viewer?", auth.authorize(token, "viewer"))

import math
import re
from collections import Counter

STOPWORDS = {
    'the', 'a', 'an', 'and', 'or', 'but', 'if', 'then', 'is', 'are', 'was', 'were',
    'to', 'of', 'in', 'on', 'for', 'with', 'as', 'by', 'at', 'from', 'that', 'this',
    'it', 'be', 'been', 'has', 'have', 'had', 'not', 'will', 'would', 'can', 'could'
}


def tokenize(text):
    """Lowercase, tokenize alphabetic words, and remove stopwords."""
    tokens = re.findall(r"\b[a-zA-Z]{2,}\b", text.lower())
    return [tok for tok in tokens if tok not in STOPWORDS]


def top_tfidf_keywords(documents, k=5):
    """Return top-k TF-IDF keywords for each document."""
    tokenized_docs = [tokenize(doc) for doc in documents]
    tf_docs = [Counter(tokens) for tokens in tokenized_docs]
    doc_count = len(documents)

    # Document frequency: number of documents containing each term
    df = Counter()
    for tokens in tokenized_docs:
        df.update(set(tokens))

    # Smoothed IDF to avoid division by zero and extreme values
    idf = {
        term: math.log((1 + doc_count) / (1 + freq)) + 1
        for term, freq in df.items()
    }

    results = []
    for tf in tf_docs:
        total_terms = sum(tf.values()) or 1
        scores = {}
        for term, count in tf.items():
            term_freq = count / total_terms
            scores[term] = term_freq * idf[term]

        ranked = sorted(scores.items(), key=lambda x: (-x[1], x[0]))[:k]
        results.append(ranked)

    return results


if __name__ == '__main__':
    docs = [
        'Natural language processing enables computers to analyze text and extract meaning from documents.',
        'Text analysis includes tokenization, frequency analysis, keyword extraction, and document scoring.',
        'Machine learning and natural language techniques are widely used in search engines and chatbots.'
    ]

    keywords = top_tfidf_keywords(docs, k=4)
    for i, doc_keywords in enumerate(keywords, 1):
        print(f'Document {i}:')
        for term, score in doc_keywords:
            print(f'  {term}: {score:.4f}')

from math import inf


def min_cost_subset(nums, target):
    # dp[s] = minimum number of elements needed to form sum s
    dp = [inf] * (target + 1)
    dp[0] = 0

    # 0/1 subset dynamic programming: iterate sums backward
    for num in nums:
        for s in range(target, num - 1, -1):
            if dp[s - num] != inf:
                dp[s] = min(dp[s], dp[s - num] + 1)

    return dp[target] if dp[target] != inf else -1


if __name__ == "__main__":
    print(min_cost_subset([3, 1, 7, 5, 9], 10))  # 2 -> 3 + 7 or 1 + 9
    print(min_cost_subset([2, 4, 6], 5))         # -1
    print(min_cost_subset([1, 2, 2, 5], 4))      # 2 -> 2 + 2
    print(min_cost_subset([8, 3, 4, 2], 14))     # 3 -> 8 + 4 + 2

import threading
import time
from functools import wraps


def ttl_memoize(ttl_seconds):
    """Thread-safe memoization decorator with TTL expiration."""
    def decorator(func):
        cache = {}
        stats = {"hits": 0, "misses": 0}
        lock = threading.RLock()

        @wraps(func)
        def wrapper(*args, **kwargs):
            # Build a hashable cache key from positional and keyword arguments.
            key = (args, tuple(sorted(kwargs.items())))
            now = time.time()

            with lock:
                if key in cache:
                    value, expires_at = cache[key]
                    if now < expires_at:
                        stats["hits"] += 1
                        return value
                    # Expired entry: remove it and recompute.
                    del cache[key]
                stats["misses"] += 1

            # Compute outside the lock to avoid blocking unrelated calls.
            result = func(*args, **kwargs)

            with lock:
                cache[key] = (result, now + ttl_seconds)
            return result

        def cache_info():
            with lock:
                # Drop expired entries before reporting size.
                now = time.time()
                expired = [k for k, (_, exp) in cache.items() if now >= exp]
                for k in expired:
                    del cache[k]
                return {
                    "hits": stats["hits"],
                    "misses": stats["misses"],
                    "size": len(cache),
                }

        wrapper.cache_info = cache_info
        return wrapper

    return decorator


@ttl_memoize(ttl_seconds=2)
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)


if __name__ == "__main__":
    print(fib(30))
    print(fib.cache_info())
    time.sleep(2.1)
    print(fib(30))  # Recomputed after TTL expiration
    print(fib.cache_info())

from configparser import ConfigParser, Error as ConfigError
from pathlib import Path


def load_app_config(path: str) -> dict:
    defaults = {
        'server': {'host': '127.0.0.1', 'port': 8080},
        'features': {'debug': False, 'caching': True},
    }

    file_path = Path(path)
    if not file_path.is_file():
        raise ValueError(f"Configuration file not found: {path}")

    parser = ConfigParser()
    try:
        read_files = parser.read(path)
        if not read_files:
            raise ValueError(f"Failed to read configuration file: {path}")
    except ConfigError as e:
        raise ValueError(f"Malformed configuration file: {e}") from e

    if 'server' not in parser:
        raise ValueError("Missing required [server] section")

    config = {
        'server': defaults['server'].copy(),
        'features': defaults['features'].copy(),
    }

    # Load and validate server settings.
    server = parser['server']
    if 'host' in server:
        config['server']['host'] = server['host'].strip()
    if not config['server']['host']:
        raise ValueError("server.host must not be empty")

    if 'port' in server:
        try:
            port = int(server['port'])
        except ValueError as e:
            raise ValueError("server.port must be an integer") from e
        if not (1 <= port <= 65535):
            raise ValueError("server.port must be between 1 and 65535")
        config['server']['port'] = port

    # Load optional feature flags as booleans.
    if 'features' in parser:
        for key in ('debug', 'caching'):
            if key in parser['features']:
                try:
                    config['features'][key] = parser['features'].getboolean(key)
                except ValueError as e:
                    raise ValueError(f"features.{key} must be a boolean") from e

    return config


if __name__ == '__main__':
    # Example usage
    try:
        cfg = load_app_config('app.ini')
        print(cfg)
    except ValueError as err:
        print(f"Error: {err}")

class TrafficLightStateMachine:
    """Simple traffic light state machine."""

    # Define valid transitions for the timer event
    _transitions = {
        'RED': 'GREEN',
        'GREEN': 'YELLOW',
        'YELLOW': 'RED'
    }

    def __init__(self):
        # Initial state
        self._state = 'RED'

    def current_state(self):
        """Return the current state."""
        return self._state

    def next_state(self):
        """Advance to the next traffic light state."""
        self._state = self._transitions[self._state]
        return self._state

    def handle(self, event):
        """Handle an event and transition if valid."""
        if event != 'timer':
            raise ValueError(f"Unsupported event: {event}")
        return self.next_state()


# Example usage
if __name__ == '__main__':
    machine = TrafficLightStateMachine()
    print(machine.current_state())  # RED
    print(machine.handle('timer'))  # GREEN
    print(machine.handle('timer'))  # YELLOW
    print(machine.handle('timer'))  # RED

from abc import ABC, abstractmethod
from math import pi


class Shape(ABC):
    """Abstract base class for geometric shapes."""

    @abstractmethod
    def area(self) -> float:
        """Return the area of the shape."""
        pass


class Rectangle(Shape):
    def __init__(self, width: float, height: float):
        self.width = self._validate_dimension(width, "width")
        self.height = self._validate_dimension(height, "height")

    @staticmethod
    def _validate_dimension(value, name: str) -> float:
        if not isinstance(value, (int, float)) or value <= 0:
            raise ValueError(f"{name} must be a positive number")
        return float(value)

    def area(self) -> float:
        return self.width * self.height


class Circle(Shape):
    def __init__(self, radius: float):
        self.radius = self._validate_dimension(radius, "radius")

    @staticmethod
    def _validate_dimension(value, name: str) -> float:
        if not isinstance(value, (int, float)) or value <= 0:
            raise ValueError(f"{name} must be a positive number")
        return float(value)

    def area(self) -> float:
        return pi * self.radius ** 2


def total_area(shapes: list[Shape]) -> float:
    """Calculate the total area of a list of Shape objects."""
    return sum(shape.area() for shape in shapes)


if __name__ == "__main__":
    shapes = [
        Rectangle(4, 5),
        Circle(3),
        Rectangle(2.5, 6)
    ]

    print(f"Total area: {total_area(shapes):.2f}")

def caesar_shift_char(ch, shift):
    """Shift a single alphabetic character, preserving case."""
    if 'a' <= ch <= 'z':
        base = ord('a')
    elif 'A' <= ch <= 'Z':
        base = ord('A')
    else:
        return ch

    return chr(base + (ord(ch) - base + shift) % 26)


def encrypt(text, shift):
    """Encrypt text using a Caesar cipher."""
    shift %= 26
    return ''.join(caesar_shift_char(ch, shift) for ch in text)


def decrypt(text, shift):
    """Decrypt text encrypted with a Caesar cipher."""
    shift %= 26
    return ''.join(caesar_shift_char(ch, -shift) for ch in text)


def main():
    message = "Attack at Dawn! Meet at Gate 3."
    shift = 5

    encrypted = encrypt(message, shift)
    decrypted = decrypt(encrypted, shift)

    print("Original :", message)
    print("Encrypted:", encrypted)
    print("Decrypted:", decrypted)


if __name__ == '__main__':
    main()

