def binary_search(scores, target):
    left = 0
    right = len(scores) - 1

    while left <= right:
        mid = (left + right) // 2

        if scores[mid] == target:
            return mid
        elif scores[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1


def main():
    scores = list(map(int, input("Enter sorted exam scores separated by spaces: ").split()))
    target = int(input("Enter the score to search for: "))

    index = binary_search(scores, target)

    if index != -1:
        print(f"Score found at index {index}.")
    else:
        print("Score not found.")


if __name__ == "__main__":
