from typing import Any, Dict, List


def validate_job(job: Dict[str, Any]) -> None:
    """Raise ValueError if the job structure or payload is invalid."""
    if "id" not in job or not isinstance(job["id"], str) or not job["id"].strip():
        raise ValueError("invalid or missing job id")

    payload = job.get("payload")
    if not isinstance(payload, list) or not payload:
        raise ValueError("payload must be a non-empty list")

    if not all(isinstance(x, (int, float)) and not isinstance(x, bool) for x in payload):
        raise ValueError("payload must contain only numbers")


def process_job(job: Dict[str, Any]) -> Dict[str, Any]:
    """Compute aggregate metrics for a valid job."""
    payload = job["payload"]
    total = sum(payload)
    return {
        "id": job["id"],
        "count": len(payload),
        "sum": total,
        "average": total / len(payload),
    }


def chunked(items: List[Dict[str, Any]], size: int) -> List[List[Dict[str, Any]]]:
    """Split items into ordered batches of at most 'size'."""
    return [items[i:i + size] for i in range(0, len(items), size)]


def run_pipeline(jobs: List[Dict[str, Any]], batch_size: int = 3) -> Dict[str, Any]:
    if batch_size <= 0:
        raise ValueError("batch_size must be greater than 0")

    processed: List[Dict[str, Any]] = []
    failed: List[Dict[str, str]] = []

    for job in jobs:
        if job.get("enabled", True) is False:
            continue

        job_id = job.get("id", "<unknown>")
        try:
            validate_job(job)
            processed.append(process_job(job))
        except ValueError as exc:
            failed.append({"id": str(job_id), "error": str(exc)})

    batches = chunked(processed, batch_size)

    return {
        "batches": batches,
        "failed": failed,
        "summary": {
            "total_jobs": len(jobs),
            "processed_jobs": len(processed),
            "failed_jobs": len(failed),
            "batch_count": len(batches),
        },
    }


if __name__ == "__main__":
    sample_jobs = [
        {"id": "job-1", "payload": [1, 2, 3]},
        {"id": "job-2", "payload": [10.5, 4.5], "enabled": True},
        {"id": "job-3", "payload": [], "enabled": True},
        {"id": "job-4", "payload": [7], "enabled": False},
        {"id": "job-5", "payload": [2, 4, 6, 8]},
    ]

    result = run_pipeline(sample_jobs, batch_size=2)
    from pprint import pprint
    pprint(result)

import argparse


def celsius_to_fahrenheit(celsius):
    return (celsius * 9 / 5) + 32


def fahrenheit_to_celsius(fahrenheit):
    return (fahrenheit - 32) * 5 / 9


def main():
    parser = argparse.ArgumentParser(
        description="Convert temperatures between Celsius and Fahrenheit."
    )
    parser.add_argument(
        "--value",
        type=float,
        required=True,
        help="Temperature value to convert"
    )
    parser.add_argument(
        "--to",
        choices=["celsius", "fahrenheit"],
        required=True,
        help="Target unit for conversion"
    )

    args = parser.parse_args()

    if args.to == "fahrenheit":
        result = celsius_to_fahrenheit(args.value)
        print(f"{args.value:.2f}°C is {result:.2f}°F")
    else:
        result = fahrenheit_to_celsius(args.value)
        print(f"{args.value:.2f}°F is {result:.2f}°C")


if __name__ == "__main__":
    main()

import json
from pathlib import Path


def fetch_config(path, required_keys):
    """Load and validate a JSON config file with explicit error handling."""
    config_path = Path(path)

    if not config_path.exists():
        raise FileNotFoundError(f"Configuration file not found: {config_path}")

    try:
        with config_path.open("r", encoding="utf-8") as f:
            data = json.load(f)
    except PermissionError:
        # Preserve permission errors unchanged.
        raise
    except json.JSONDecodeError as exc:
        raise ValueError(f"Invalid JSON in configuration file: {config_path}") from exc
    except OSError as exc:
        raise OSError(f"Failed to read configuration file: {config_path}") from exc

    if not isinstance(data, dict):
        raise TypeError("Configuration root must be a JSON object")

    missing = [key for key in required_keys if key not in data]
    if missing:
        raise KeyError(f"Missing required configuration keys: {', '.join(missing)}")

    return data


def main():
    required = ["host", "port", "debug"]
    path = "config.json"

    try:
        config = fetch_config(path, required)
    except (FileNotFoundError, ValueError, TypeError, KeyError, OSError) as exc:
        print(f"Error: {exc}")
    else:
        print("Loaded config:", config)


if __name__ == "__main__":
    main()

import time


class Timer:
    def __init__(self, label: str):
        self.label = label
        self.elapsed = None
        self._start = None

    def __enter__(self):
        self._start = time.perf_counter()
        print(f"[{self.label}] Starting...")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        end = time.perf_counter()
        self.elapsed = end - self._start
        print(f"[{self.label}] Finished in {self.elapsed:.6f} seconds")
        # Return False so any exception inside the block is re-raised
        return False


if __name__ == "__main__":
    with Timer("Loop test") as timer:
        total = 0
        for i in range(1_000_000):
            total += i

    print(f"Computed total: {total}")
    print(f"Measured time: {timer.elapsed:.6f} seconds")

