class EventBus:
    def __init__(self):
        self._listeners = {}

    def subscribe(self, event_name, listener):
        """Register a listener function for an event."""
        self._listeners.setdefault(event_name, []).append(listener)

    def emit(self, event_name, data):
        """Notify all listeners subscribed to an event."""
        for listener in self._listeners.get(event_name, []):
            listener(data)


class TaskManager:
    def __init__(self, event_bus):
        self.event_bus = event_bus
        self.tasks = {}
        self.next_id = 1

    def add_task(self, title):
        task = {
            'id': self.next_id,
            'title': title,
            'completed': False
        }
        self.tasks[self.next_id] = task
        self.next_id += 1
        self.event_bus.emit('task_added', task)
        return task['id']

    def complete_task(self, task_id):
        task = self.tasks.get(task_id)
        if task and not task['completed']:
            task['completed'] = True
            self.event_bus.emit('task_completed', task)

    def remove_task(self, task_id):
        task = self.tasks.pop(task_id, None)
        if task:
            self.event_bus.emit('task_removed', task)


# Event listeners

