class BloomFilter:
    def __init__(self, size=20):
        # Bit array initialized to 0
        self.size = size
        self.bits = [0] * size

    def _hashes(self, item):
        # Two simple hash positions
        h1 = hash(item) % self.size
        h2 = hash("salt_" + item) % self.size
        return h1, h2

    def add(self, item):
        # Set both hash positions to 1
        h1, h2 = self._hashes(item)
        self.bits[h1] = 1
        self.bits[h2] = 1

    def might_contain(self, item):
        # Item might be present only if both bits are set
        h1, h2 = self._hashes(item)
        return self.bits[h1] == 1 and self.bits[h2] == 1


def main():
    bloom = BloomFilter(size=20)

    # Add some words
    words_to_add = ["apple", "banana", "orange"]
    for word in words_to_add:
        bloom.add(word)

    # Test membership
    test_words = ["apple", "banana", "grape", "melon", "orange"]
    for word in test_words:
        if bloom.might_contain(word):
            print(f"{word}: might be in the filter")
        else:
            print(f"{word}: definitely not in the filter")

    # Optional: show internal bit array
    print("Bit array:", bloom.bits)


if __name__ == "__main__":
    main()
