from urllib.parse import urlsplit, urlunsplit, parse_qsl, urlencode
import posixpath


def normalize_tracking_url(url: str, overrides: dict | None = None) -> str:
    """Return a normalized URL with tracking parameters removed and query overrides applied."""
    parts = urlsplit(url)

    if not parts.scheme or not parts.hostname:
        raise ValueError("URL must include both a scheme and a hostname")

    scheme = parts.scheme.lower()
    hostname = parts.hostname.lower()
    port = parts.port

    # Rebuild netloc with optional userinfo and non-default port.
    userinfo = ""
    if parts.username is not None:
        userinfo = parts.username
        if parts.password is not None:
            userinfo += f":{parts.password}"
        userinfo += "@"

    default_port = (scheme == "http" and port == 80) or (scheme == "https" and port == 443)
    hostport = hostname if port is None or default_port else f"{hostname}:{port}"
    netloc = f"{userinfo}{hostport}"

    # Collapse repeated slashes and keep path absolute if it originally was.
    path = parts.path or "/"
    normalized_path = posixpath.normpath(path)
    if path.startswith("/") and not normalized_path.startswith("/"):
        normalized_path = "/" + normalized_path
    if normalized_path == ".":
        normalized_path = "/"

    # Remove tracking params.
    blocked = {"fbclid", "gclid"}
    query_items = [
        (k, v)
        for k, v in parse_qsl(parts.query, keep_blank_values=True)
        if not (k.startswith("utm_") or k in blocked)
    ]

    # Apply overrides by replacing existing keys.
    overrides = overrides or {}
    if overrides:
        override_keys = set(overrides)
        query_items = [(k, v) for k, v in query_items if k not in override_keys]
        for key, value in overrides.items():
            query_items.append((str(key), str(value)))

    query_items.sort(key=lambda item: (item[0], item[1]))
    query = urlencode(query_items, doseq=True)

    return urlunsplit((scheme, netloc, normalized_path, query, parts.fragment))


