from html.parser import HTMLParser
import xml.etree.ElementTree as ET


def extract_catalog(html: str, xml_feed: str) -> list[dict]:
    class ProductHTMLParser(HTMLParser):
        def __init__(self):
            super().__init__()
            self.products = {}
            self.current_id = None
            self.current_field = None
            self.buffer = []

        def handle_starttag(self, tag, attrs):
            attrs = dict(attrs)
            if tag == 'div' and attrs.get('class') == 'product' and 'data-id' in attrs:
                self.current_id = attrs['data-id'].strip()
                self.products[self.current_id] = {'name': None, 'price': None}
            elif self.current_id is not None and tag == 'h2':
                self.current_field = 'name'
                self.buffer = []
            elif self.current_id is not None and tag == 'span' and attrs.get('class') == 'price':
                self.current_field = 'price'
                self.buffer = []

        def handle_data(self, data):
            if self.current_field is not None:
                self.buffer.append(data)

        def handle_endtag(self, tag):
            if self.current_id is None:
                return

            if self.current_field == 'name' and tag == 'h2':
                self.products[self.current_id]['name'] = ''.join(self.buffer).strip()
                self.current_field = None
            elif self.current_field == 'price' and tag == 'span':
                self.products[self.current_id]['price'] = ''.join(self.buffer).strip()
                self.current_field = None
            elif tag == 'div':
                self.current_id = None
                self.current_field = None
                self.buffer = []

    # Parse HTML products
    html_parser = ProductHTMLParser()
    html_parser.feed(html)

    # Parse XML products
    xml_products = {}
    root = ET.fromstring(xml_feed)
    for product in root.findall('.//product'):
        product_id = (product.get('id') or '').strip()
        stock = product.findtext('stock', default='').strip()
        category = product.findtext('category', default='').strip()
        if product_id:
            xml_products[product_id] = {'stock': stock, 'category': category}

    # Merge valid entries present in both sources
    merged = []
    for product_id, html_data in html_parser.products.items():
        if product_id not in xml_products:
            continue

        try:
            merged.append({
                'id': int(product_id),
                'name': html_data['name'].strip(),
                'price': float(html_data['price'].replace('$', '').strip()),
                'stock': int(xml_products[product_id]['stock']),
                'category': xml_products[product_id]['category']
            })
        except (ValueError, AttributeError):
            # Skip malformed entries with missing or invalid values
            continue

    return sorted(merged, key=lambda item: item['id'])

class MaxStack:
    def __init__(self):
        self.data = []
        self.max_data = []

    def push(self, value):
        self.data.append(value)
        current_max = value if not self.max_data else max(value, self.max_data[-1])
        self.max_data.append(current_max)

    def pop(self):
        if not self.data:
            raise IndexError('pop from empty stack')
        self.max_data.pop()
        return self.data.pop()

    def max(self):
        if not self.max_data:
            raise IndexError('max from empty stack')
        return self.max_data[-1]

    def __bool__(self):
        return bool(self.data)


class MaxQueue:
    def __init__(self):
        # Two stacks provide amortized O(1) queue operations.
        self.in_stack = MaxStack()
        self.out_stack = MaxStack()

    def enqueue(self, value):
        self.in_stack.push(value)

    def _shift(self):
        if not self.out_stack:
            while self.in_stack:
                self.out_stack.push(self.in_stack.pop())

    def dequeue(self):
        self._shift()
        if not self.out_stack:
            raise IndexError('dequeue from empty queue')
        return self.out_stack.pop()

    def max(self):
        in_has = bool(self.in_stack)
        out_has = bool(self.out_stack)
        if not in_has and not out_has:
            raise IndexError('max from empty queue')
        if in_has and out_has:
            return max(self.in_stack.max(), self.out_stack.max())
        return self.in_stack.max() if in_has else self.out_stack.max()

    def __bool__(self):
        return bool(self.in_stack) or bool(self.out_stack)


class MaxQueueStackProcessor:
    def __init__(self):
        self.queue = MaxQueue()
        self.stack = MaxStack()

    def process(self, commands):
        outputs = []

        for command in commands:
            parts = command.split()
            op = parts[0]

            if op == 'ENQUEUE':
                self.queue.enqueue(int(parts[1]))
            elif op == 'DEQUEUE':
                outputs.append(self.queue.dequeue())
            elif op == 'PUSH':
                self.stack.push(int(parts[1]))
            elif op == 'POP':
                outputs.append(self.stack.pop())
            elif op == 'MAX':
                queue_has = bool(self.queue)
                stack_has = bool(self.stack)
                if not queue_has and not stack_has:
                    raise IndexError('max from empty processor')
                if queue_has and stack_has:
                    outputs.append(max(self.queue.max(), self.stack.max()))
                elif queue_has:
                    outputs.append(self.queue.max())
                else:
                    outputs.append(self.stack.max())
            else:
                raise ValueError(f'unknown command: {command}')

        return outputs


