import math
import hashlib


class BloomFilter:
    def __init__(self, capacity: int, error_rate: float):
        if capacity <= 0:
            raise ValueError("capacity must be > 0")
        if not (0 < error_rate < 1):
            raise ValueError("error_rate must be between 0 and 1")

        self.capacity = capacity
        self.error_rate = error_rate
        self.size = self._optimal_size(capacity, error_rate)
        self.num_hashes = self._optimal_hashes(self.size, capacity)
        self.bit_array = bytearray((self.size + 7) // 8)
        self.count = 0

    @staticmethod
    def _optimal_size(n: int, p: float) -> int:
        # m = -(n * ln(p)) / (ln(2)^2)
        return max(8, math.ceil(-(n * math.log(p)) / (math.log(2) ** 2)))

    @staticmethod
    def _optimal_hashes(m: int, n: int) -> int:
        # k = (m / n) * ln(2)
        return max(1, round((m / n) * math.log(2)))

    @staticmethod
    def _to_bytes(item) -> bytes:
        if isinstance(item, bytes):
            return item
        if isinstance(item, str):
            return item.encode("utf-8")
        raise TypeError("item must be str or bytes")

    def _hashes(self, item):
        data = self._to_bytes(item)

        # Double hashing: h_i(x) = h1(x) + i*h2(x) mod m
        digest1 = hashlib.sha256(b"A" + data).digest()
        digest2 = hashlib.sha256(b"B" + data).digest()
        h1 = int.from_bytes(digest1, "big")
        h2 = int.from_bytes(digest2, "big") or 1  # avoid zero step

        for i in range(self.num_hashes):
            yield (h1 + i * h2) % self.size

    def _set_bit(self, index: int) -> None:
        byte_index, bit_index = divmod(index, 8)
        self.bit_array[byte_index] |= 1 << bit_index

    def _get_bit(self, index: int) -> bool:
        byte_index, bit_index = divmod(index, 8)
        return bool(self.bit_array[byte_index] & (1 << bit_index))

    def add(self, item) -> None:
        for index in self._hashes(item):
            self._set_bit(index)
        self.count += 1

    def __contains__(self, item) -> bool:
        return all(self._get_bit(index) for index in self._hashes(item))

    def stats(self) -> dict:
        # Estimated false positive rate after count insertions:
        # p ~= (1 - e^(-k * n / m))^k
        est_fp = (1 - math.exp(-self.num_hashes * self.count / self.size)) ** self.num_hashes
        return {
            "size_bits": self.size,
            "num_hashes": self.num_hashes,
            "inserted_count": self.count,
            "estimated_false_positive_rate": est_fp,
        }


