from dataclasses import dataclass, replace
from typing import Any


@dataclass(frozen=True)
class AppConfig:
    host: str
    port: int
    debug: bool
    tags: tuple[str, ...]
    metadata: dict[str, str]

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> AppConfig:
        required = {"host", "port", "debug", "tags", "metadata"}
        missing = required - data.keys()
        if missing:
            raise ValueError(f"Missing required fields: {', '.join(sorted(missing))}")

        host = data["host"]
        port = data["port"]
        debug = data["debug"]
        tags = data["tags"]
        metadata = data["metadata"]

        if not isinstance(host, str):
            raise ValueError("host must be a str")
        if not isinstance(port, int) or isinstance(port, bool):
            raise ValueError("port must be an int")
        if not isinstance(debug, bool):
            raise ValueError("debug must be a bool")
        if not isinstance(tags, (list, tuple)):
            raise ValueError("tags must be a list or tuple of str")
        if not all(isinstance(tag, str) for tag in tags):
            raise ValueError("each tag must be a str")
        if not isinstance(metadata, dict):
            raise ValueError("metadata must be a dict[str, str]")
        if not all(isinstance(k, str) and isinstance(v, str) for k, v in metadata.items()):
            raise ValueError("metadata must contain only str keys and str values")

        return cls(
            host=host,
            port=port,
            debug=debug,
            tags=tuple(tags),
            metadata=dict(metadata),
        )

    def with_overrides(self, **kwargs: Any) -> AppConfig:
        allowed = {"host", "port", "debug", "tags", "metadata"}
        unknown = set(kwargs) - allowed
        if unknown:
            raise ValueError(f"Unknown override fields: {', '.join(sorted(unknown))}")

        updated = {
            "host": self.host,
            "port": self.port,
            "debug": self.debug,
            "tags": self.tags,
            "metadata": self.metadata,
        }
        updated.update(kwargs)

        # Reuse validation and normalization logic.
        validated = AppConfig.from_dict(updated)
        return replace(self, **validated.__dict__)

