class ConfigError(Exception):
    """Base class for configuration validation errors."""

    def __init__(self, section, message):
        self.section = section
        self.message = message
        super().__init__(f"[{section}] {message}")


class MissingFieldError(ConfigError):
    """Raised when a required section or field is missing."""
    pass


class InvalidTypeError(ConfigError):
    """Raised when a field has an unexpected type."""
    pass


class RangeError(ConfigError):
    """Raised when a numeric field is outside the allowed range."""
    pass


def validate_config(config):
    """Validate deployment configuration structure and values."""
    schema = {
        "database": {
            "host": (str, None),
            "port": (int, (1, 65535)),
        },
        "service": {
            "name": (str, None),
            "workers": (int, (1, 64)),
        },
    }

    for section, fields in schema.items():
        if section not in config:
            raise MissingFieldError(section, "missing required section")
        if not isinstance(config[section], dict):
            raise InvalidTypeError(section, "section must be a dictionary")

        for field, (expected_type, valid_range) in fields.items():
            if field not in config[section]:
                raise MissingFieldError(section, f"missing required field '{field}'")

            value = config[section][field]
            if not isinstance(value, expected_type):
                raise InvalidTypeError(
                    section,
                    f"field '{field}' must be of type {expected_type.__name__}"
                )

            if valid_range is not None:
                low, high = valid_range
                if not (low <= value <= high):
                    raise RangeError(
                        section,
                        f"field '{field}' must be between {low} and {high}"
                    )

    return True


