def process_events(events):
    """Parse, validate, and sort event records by start time."""
    processed = []
    date_format = "%Y-%m-%d %H:%M"

    for event in events:
        try:
            start_dt = datetime.strptime(event['start'], date_format)
            end_dt = datetime.strptime(event['end'], date_format)
        except (KeyError, ValueError):
            # Skip records with missing fields or invalid datetime strings
            continue

        if end_dt < start_dt:
            # Skip invalid ranges
            continue

        duration_minutes = int((end_dt - start_dt).total_seconds() // 60)

        processed.append({
            'name': event.get('name', 'Unnamed Event'),
            'start': start_dt.isoformat(timespec='minutes'),
            'end': end_dt.isoformat(timespec='minutes'),
            'duration_minutes': duration_minutes
        })

    # Sort by parsed start datetime
    processed.sort(key=lambda item: item['start'])
    return processed


