import re
from typing import Any, Dict, List


def validate(schema: Dict[str, Any], data: Any, path: str = "") -> List[str]:
    errors: List[str] = []

    # Object schema: field -> rule dict
    if isinstance(schema, dict) and "type" not in schema:
        if not isinstance(data, dict):
            return [f"{path or 'root'}: expected object, got {type(data).__name__}"]

        for field, rules in schema.items():
            field_path = f"{path}.{field}" if path else field
            required = rules.get("required", False)

            if field not in data:
                if required:
                    errors.append(f"{field_path}: missing required field")
                continue

            errors.extend(validate(rules, data[field], field_path))
        return errors

    # Rule dict
    expected_type = schema.get("type")
    nullable = schema.get("nullable", False)

    if data is None:
        if not nullable:
            errors.append(f"{path}: value cannot be null")
        return errors

    if expected_type == list:
        if not isinstance(data, list):
            return [f"{path}: expected list, got {type(data).__name__}"]
        item_schema = schema.get("items")
        if item_schema is not None:
            for i, item in enumerate(data):
                errors.extend(validate(item_schema, item, f"{path}[{i}]") )
        return errors

    if expected_type == dict:
        nested_schema = schema.get("schema", {})
        if not isinstance(data, dict):
            return [f"{path}: expected dict, got {type(data).__name__}"]
        errors.extend(validate(nested_schema, data, path))
        return errors

    if expected_type and not isinstance(data, expected_type):
        return [f"{path}: expected {expected_type.__name__}, got {type(data).__name__}"]

    if "enum" in schema and data not in schema["enum"]:
        errors.append(f"{path}: must be one of {schema['enum']}")

    if isinstance(data, str) and "pattern" in schema:
        if not re.fullmatch(schema["pattern"], data):
            errors.append(f"{path}: does not match required pattern")

    if isinstance(data, (int, float)):
        if "min" in schema and data < schema["min"]:
            errors.append(f"{path}: must be >= {schema['min']}")
        if "max" in schema and data > schema["max"]:
            errors.append(f"{path}: must be <= {schema['max']}")

    return errors


