class NonNegative:
    """Descriptor that allows only non-negative numeric values."""

    def __set_name__(self, owner, name):
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name)

    def __set__(self, instance, value):
        if not isinstance(value, (int, float)):
            raise TypeError("Value must be a number")
        if value < 0:
            raise ValueError("Value cannot be negative")
        setattr(instance, self.private_name, float(value))


class Temperature:
    # Descriptor-managed attribute
    kelvin = NonNegative()

    def __init__(self, kelvin):
        self.kelvin = kelvin

    @property
    def celsius(self):
        """Convert stored Kelvin temperature to Celsius."""
        return self.kelvin - 273.15

    @celsius.setter
    def celsius(self, value):
        """Set temperature in Celsius, storing the result in Kelvin."""
        self.kelvin = value + 273.15


