import hashlib
import sys
from pathlib import Path


def sha256_file(path, chunk_size=8192):
    """Return the SHA-256 hex digest of a file, or None if unreadable."""
    hasher = hashlib.sha256()
    try:
        with open(path, 'rb') as f:
            while True:
                chunk = f.read(chunk_size)
                if not chunk:
                    break
                hasher.update(chunk)
        return hasher.hexdigest()
    except (OSError, PermissionError):
        return None


def verify_files(file_paths):
    """Map each file path to its SHA-256 checksum or None on failure."""
    results = {}
    for file_path in file_paths:
        path_str = str(Path(file_path))
        results[path_str] = sha256_file(path_str)
    return results


