    md5_hash = hashlib.md5()
    sha256_hash = hashlib.sha256()

    with open(file_path, 'rb') as file:
        # Read the file in chunks to handle large files efficiently
        for chunk in iter(lambda: file.read(4096), b''):
            md5_hash.update(chunk)
            sha256_hash.update(chunk)

    return md5_hash.hexdigest(), sha256_hash.hexdigest()


def main():
    file_path = input('Enter the path to a file: ').strip()

    if not os.path.isfile(file_path):
        print('Error: File not found.')
        return

    try:
        md5_result, sha256_result = calculate_checksums(file_path)
        print(f'MD5: {md5_result}')
        print(f'SHA-256: {sha256_result}')
    except OSError as error:
        print(f'Error reading file: {error}')


if __name__ == '__main__':
    main()

def find_kth_smallest(nums, k):
    """Return the k-th smallest element (1-based) using Quickselect."""
    if not 1 <= k <= len(nums):
        raise ValueError("k must be between 1 and the length of the list")

    arr = nums[:]  # Work on a copy to avoid modifying the input
    target_index = k - 1

    def partition(left, right):
        pivot = arr[right]
        store_index = left
        for i in range(left, right):
            if arr[i] <= pivot:
                arr[store_index], arr[i] = arr[i], arr[store_index]
                store_index += 1
        arr[store_index], arr[right] = arr[right], arr[store_index]
        return store_index

    left, right = 0, len(arr) - 1
    while left <= right:
        pivot_index = partition(left, right)
        if pivot_index == target_index:
            return arr[pivot_index]
        elif pivot_index < target_index:
            left = pivot_index + 1
        else:
            right = pivot_index - 1


def binary_search(sorted_nums, target):
    """Return the index of target in sorted_nums, or -1 if not found."""
    left, right = 0, len(sorted_nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if sorted_nums[mid] == target:
            return mid
        if sorted_nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1


if __name__ == "__main__":
    numbers = [12, 7, 3, 19, 5, 8, 14, 1]
    k = 4

    kth_smallest = find_kth_smallest(numbers, k)
    sorted_numbers = sorted(numbers)

    print("Original list:", numbers)
    print("Sorted list:", sorted_numbers)
    print(f"{k}-th smallest element:", kth_smallest)

    for target in [8, 10]:
        index = binary_search(sorted_numbers, target)
        print(f"Search for {target}: index {index}")

from abc import ABC, abstractmethod
from itertools import count


class PaymentProcessor(ABC):
    def __init__(self):
        self.transactions = {}
        self._ids = count(1)

    def _new_transaction(self, amount):
        tx_id = f"TX-{next(self._ids)}"
        self.transactions[tx_id] = {
            "authorized": amount,
            "captured": 0.0,
            "refunded": 0.0,
            "status": "authorized",
        }
        return tx_id

    @abstractmethod
    def authorize(self, amount):
        pass

    @abstractmethod
    def capture(self, transaction_id):
        pass

    @abstractmethod
    def refund(self, transaction_id, amount):
        pass


class CreditCardProcessor(PaymentProcessor):
    def authorize(self, amount):
        if amount <= 0:
            raise ValueError("Authorization amount must be positive")
        return self._new_transaction(amount)

    def capture(self, transaction_id):
        tx = self.transactions.get(transaction_id)
        if not tx:
            raise KeyError("Transaction not found")
        if tx["status"] != "authorized":
            raise ValueError("Capture allowed only after authorization")
        tx["captured"] = tx["authorized"]
        tx["status"] = "captured"
        return tx

    def refund(self, transaction_id, amount):
        tx = self.transactions.get(transaction_id)
        if not tx:
            raise KeyError("Transaction not found")
        if amount <= 0:
            raise ValueError("Refund amount must be positive")
        if tx["captured"] == 0:
            raise ValueError("Cannot refund before capture")
        if tx["refunded"] + amount > tx["captured"]:
            raise ValueError("Refund exceeds captured amount")
        tx["refunded"] += amount
        tx["status"] = "refunded" if tx["refunded"] == tx["captured"] else "partially_refunded"
        return tx


class PayPalProcessor(PaymentProcessor):
    def authorize(self, amount):
        if amount < 1:
            raise ValueError("PayPal requires at least 1 unit to authorize")
        return self._new_transaction(amount)

    def capture(self, transaction_id):
        tx = self.transactions.get(transaction_id)
        if not tx:
            raise KeyError("Transaction not found")
        if tx["status"] != "authorized":
            raise ValueError("Capture allowed only after authorization")
        tx["captured"] = tx["authorized"]
        tx["status"] = "captured"
        return tx

    def refund(self, transaction_id, amount):
        tx = self.transactions.get(transaction_id)
        if not tx:
            raise KeyError("Transaction not found")
        if amount <= 0:
            raise ValueError("Refund amount must be positive")
        if tx["captured"] == 0:
            raise ValueError("Cannot refund before capture")
        if tx["refunded"] + amount > tx["captured"]:
            raise ValueError("Refund exceeds captured amount")
        tx["refunded"] += amount
        tx["status"] = "refunded" if tx["refunded"] == tx["captured"] else "partially_refunded"
        return tx


if __name__ == "__main__":
    cc = CreditCardProcessor()
    pp = PayPalProcessor()

    cc_tx = cc.authorize(120.0)
    cc.capture(cc_tx)
    cc.refund(cc_tx, 20.0)

    pp_tx = pp.authorize(75.0)
    pp.capture(pp_tx)
    pp.refund(pp_tx, 75.0)

    print("CreditCard transactions:")
    print(cc.transactions)
    print("PayPal transactions:")
    print(pp.transactions)

import sys
import heapq


def solve():
    input = sys.stdin.readline
    n = int(input().strip())

    # Max-heap simulated with negative priority.
    # Each entry: (-priority, task_id)
    heap = []

    # Maps task_id to its current valid priority.
    current = {}

    def clean_top():
        # Remove outdated heap entries until top is valid.
        while heap:
            neg_priority, task_id = heap[0]
            priority = -neg_priority
            if task_id in current and current[task_id] == priority:
                return
            heapq.heappop(heap)

    out = []

    for _ in range(n):
        parts = input().strip().split()
        cmd = parts[0]

        if cmd == 'ADD':
            task_id = parts[1]
            priority = int(parts[2])
            current[task_id] = priority
            heapq.heappush(heap, (-priority, task_id))

        elif cmd == 'UPDATE':
            task_id = parts[1]
            priority = int(parts[2])
            if task_id in current:
                current[task_id] = priority
                heapq.heappush(heap, (-priority, task_id))

        elif cmd == 'POP':
            clean_top()
            if not heap:
                out.append('EMPTY')
            else:
                neg_priority, task_id = heapq.heappop(heap)
                if task_id in current:
                    del current[task_id]
                out.append(task_id)

        elif cmd == 'PEEK':
            clean_top()
            if not heap:
                out.append('EMPTY')
            else:
                out.append(heap[0][1])

    sys.stdout.write('\n'.join(out))


if __name__ == '__main__':
    solve()

import os
from typing import Any, Dict


def _parse_bool(value: str) -> bool:
    truthy = {"true", "1", "yes", "y", "on"}
    falsy = {"false", "0", "no", "n", "off"}
    normalized = value.strip().lower()
    if normalized in truthy:
        return True
    if normalized in falsy:
        return False
    raise ValueError(f"invalid boolean value: {value!r}")


def _convert_value(name: str, raw: str, rules: Dict[str, Any]) -> Any:
    expected_type = rules.get("type", str)

    if expected_type is str:
        value = raw
    elif expected_type is int:
        value = int(raw)
    elif expected_type is bool:
        value = _parse_bool(raw)
    elif expected_type is list:
        separator = rules.get("separator", ",")
        value = [item.strip() for item in raw.split(separator) if item.strip()]
    else:
        raise ValueError(f"{name}: unsupported type {expected_type!r}")

    choices = rules.get("choices")
    if choices is not None:
        invalid = [item for item in value] if isinstance(value, list) else [value]
        invalid = [item for item in invalid if item not in choices]
        if invalid:
            raise ValueError(f"{name}: invalid choice(s) {invalid!r}, allowed: {sorted(choices)!r}")

    return value


def load_config(schema: Dict[str, Dict[str, Any]]) -> Dict[str, Any]:
    config = {}
    errors = []

    for name, rules in schema.items():
        raw = os.environ.get(name)
        required = rules.get("required", False)

        if raw is None or raw == "":
            if "default" in rules:
                config[name] = rules["default"]
            elif required:
                errors.append(f"{name}: required environment variable is missing")
            continue

        try:
            config[name] = _convert_value(name, raw, rules)
        except Exception as exc:
            errors.append(f"{name}: {exc}")

    if errors:
        raise ValueError("Configuration errors:\n- " + "\n- ".join(errors))

    return config


if __name__ == "__main__":
    schema = {
        "APP_ENV": {"type": str, "required": True, "choices": {"dev", "staging", "prod"}},
        "PORT": {"type": int, "default": 8080},
        "DEBUG": {"type": bool, "default": False},
        "ALLOWED_HOSTS": {"type": list, "default": [], "separator": ","},
    }

    try:
        settings = load_config(schema)
        print(settings)
    except ValueError as err:
        print(err)

import json
import hashlib

SHARED_SECRET = "my_webhook_secret"


def handle_webhook(payload, signature):
    """Validate a webhook signature and process the JSON payload."""
    # Create the expected signature from the payload and shared secret
    expected_signature = hashlib.sha256((payload + SHARED_SECRET).encode("utf-8")).hexdigest()

    if signature != expected_signature:
        return {"status": "error", "message": "Invalid signature"}

    try:
        data = json.loads(payload)
    except json.JSONDecodeError:
        return {"status": "error", "message": "Invalid JSON payload"}

    event = data.get("event")
    if not event:
        return {"status": "error", "message": "Missing event field"}

    return {"status": "success", "message": f"Received event: {event}"}


# Example usage
if __name__ == "__main__":
    payload = json.dumps({"event": "order.created", "order_id": 123})
    signature = hashlib.sha256((payload + SHARED_SECRET).encode("utf-8")).hexdigest()

    result = handle_webhook(payload, signature)
    print(result)

from threading import Lock


class SingletonMeta(type):
    """Thread-safe Singleton metaclass."""
    _instances = {}
    _lock = Lock()

    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            with cls._lock:
                if cls not in cls._instances:
                    cls._instances[cls] = super().__call__(*args, **kwargs)
        return cls._instances[cls]


class ProcessorRegistry(metaclass=SingletonMeta):
    def __init__(self):
        self._processors = {}
        self._registry_lock = Lock()

    def register(self, name):
        """Decorator to register a processor class under a unique name."""
        def decorator(cls):
            with self._registry_lock:
                if name in self._processors:
                    raise ValueError(f"Processor '{name}' is already registered")
                self._processors[name] = cls
            return cls
        return decorator

    def create(self, name, **kwargs):
        """Instantiate a registered processor by name."""
        try:
            processor_cls = self._processors[name]
        except KeyError:
            raise KeyError(f"Unknown processor: '{name}'") from None
        return processor_cls(**kwargs)

    def list_processors(self):
        """Return registered processor names in sorted order."""
        return sorted(self._processors.keys())


registry = ProcessorRegistry()


@registry.register("upper")
class UpperCaseProcessor:
    def process(self, text):
        return text.upper()


@registry.register("prefix")
class PrefixProcessor:
    def __init__(self, prefix=""):
        self.prefix = prefix

    def process(self, text):
        return f"{self.prefix}{text}"


if __name__ == "__main__":
    upper = registry.create("upper")
    prefix = registry.create("prefix", prefix="LOG: ")

    print(registry.list_processors())
    print(upper.process("hello world"))
    print(prefix.process("system ready"))

from abc import ABC, abstractmethod


class DiscountStrategy(ABC):
    """Abstract strategy for applying discounts."""

    @abstractmethod
    def apply_discount(self, total):
        pass


class NoDiscount(DiscountStrategy):
    def apply_discount(self, total):
        return total


class PercentageDiscount(DiscountStrategy):
    def __init__(self, percent):
        self.percent = percent

    def apply_discount(self, total):
        return total - (total * self.percent / 100)


class FixedDiscount(DiscountStrategy):
    def __init__(self, amount):
        self.amount = amount

    def apply_discount(self, total):
        return max(0, total - self.amount)


class Cart:
    """Context class that uses a discount strategy."""

    def __init__(self, total, strategy):
        self.total = total
        self.strategy = strategy

    def set_strategy(self, strategy):
        self.strategy = strategy

    def final_price(self):
        return self.strategy.apply_discount(self.total)


# Demonstration
cart = Cart(50, NoDiscount())
print('No discount:', cart.final_price())

cart.set_strategy(PercentageDiscount(10))
print('10% discount:', cart.final_price())

cart.set_strategy(FixedDiscount(5))
print('$5 discount:', cart.final_price())

from typing import Any, Dict, List


def summarize_patient_risk(patients: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    results = []
    required_scores = ["fever", "cough", "fatigue"]

    for patient in patients:
        if not isinstance(patient, dict):
            continue

        if "name" not in patient:
            continue

        valid = True
        total_score = 0

        for score_name in required_scores:
            if score_name not in patient:
                valid = False
                break

            score_value = patient[score_name]

            if not isinstance(score_value, (int, float)):
                valid = False
                break

            total_score += score_value

        if not valid:
            continue

        if 0 <= total_score <= 9:
            risk_level = "Low"
        elif 10 <= total_score <= 19:
            risk_level = "Moderate"
        elif 20 <= total_score <= 30:
            risk_level = "High"
        else:
            continue

        results.append(
            {
                "name": patient["name"],
                "total_score": total_score,
                "risk_level": risk_level,
            }
        )

    return results

from typing import Callable, Dict, List, Any

Request = Dict[str, Any]
Response = Dict[str, Any]
Middleware = Callable[[Request, Callable[[Request], Response]], Response]
Handler = Callable[[Request], Response]


class Pipeline:
    def __init__(self) -> None:
        self._middleware: List[Middleware] = []

    def add(self, middleware: Middleware) -> None:
        self._middleware.append(middleware)

    def execute(self, request: Request, handler: Handler) -> Response:
        # Build the middleware chain from last to first.
        next_handler = handler
        for middleware in reversed(self._middleware):
            current_next = next_handler

            def wrapped(req: Request, mw: Middleware = middleware, nxt: Handler = current_next) -> Response:
                return mw(req, nxt)

            next_handler = wrapped
        return next_handler(request)


logs: List[str] = []


def logging_middleware(request: Request, next_fn: Handler) -> Response:
    logs.append(f"REQUEST {request.get('path', '')}")
    response = next_fn(request)
    response["logged"] = True
    return response


def default_user_middleware(request: Request, next_fn: Handler) -> Response:
    request.setdefault("user", "guest")
    return next_fn(request)


def admin_guard_middleware(request: Request, next_fn: Handler) -> Response:
    path = request.get("path", "")
    user = request.get("user")
    if path.startswith("/admin") and user != "admin":
        return {"status": 403, "message": "Forbidden"}
    return next_fn(request)


def final_handler(request: Request) -> Response:
    return {
        "status": 200,
        "message": f"Hello {request['user']}, you requested {request.get('path', '')}"
    }


pipeline = Pipeline()
pipeline.add(logging_middleware)
pipeline.add(default_user_middleware)
pipeline.add(admin_guard_middleware)

sample_requests = [
    {"path": "/home"},
    {"path": "/admin/settings", "user": "guest"},
    {"path": "/admin/dashboard", "user": "admin"},
]

for req in sample_requests:
    response = pipeline.execute(req.copy(), final_handler)
    print(response)

